/* 1) 还原视角 (跟 getViewpoint 配对) */
const saved = ssp.cameraController.getViewpoint();
ssp.cameraController.flyTo({ position: { x: 100, y: 50, z: 100 }, target: { x: 0, y: 0, z: 0 } });
/* 1 秒后瞬移回来 */
setTimeout(() => ssp.cameraController.setViewpoint(saved), 1000);

/* 2) 直接设视角 */
ssp.cameraController.setViewpoint({
  position: { x: 5, y: 3, z: 8 },
  target: { x: 0, y: 0, z: 0 },
});

/* 3) 带旋转 */
ssp.cameraController.setViewpoint({
  position: { x: 0, y: 5, z: 10 },
  target: { x: 0, y: 0, z: 0 },
  rotation: { x: 0, y: Math.PI / 2, z: 0 },
});
